354	cast! {
355	    type Selector,
356	    text: EcoString => Self::text(&text)?,
357	    func: Func => func
358	        .to_element()
359	        .ok_or("only element functions can be used as selectors")?
360	        .select(),
361	    label: Label => Self::Label(label),
362	    regex: Regex => Self::regex(regex)?,
363	    location: Location => Self::Location(location),
364	}
